"normalized_unit\": { \"type\": [\"string\", \"null\"] },\n          \"source_document\": { \"type\": \"string\" },\n          \"page\": { \"type\": [\"string\", \"integer\"] },\n          \"evidence_text\": { \"type\": \"string\" },\n          \"missing_conditions\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n          \"confidence\": { \"enum\": [\"high\", \"medium\", \"low\"] },\n          \"confidence_reasons\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n          \"review_required\": { \"type\": \"boolean\" }\n        }\n      }\n    },\n    \"missing_conditions\": { \"type\": \"array\" },\n    \"conflicts\": { \"type\": \"array\" },\n    \"review_queue\": { \"type\": \"array\" }\n  }\n}\n",
